320:export type PromptInput<Tool extends ToolRegistration = ToolRegistration> = {
321-    readonly conversationId: ConversationId;
322-    /** The request's resolution; `agent.tools` are the tools offered in this request. */
323-    readonly agent: Agent<Tool>;
324-    /** Built by `HarnessOptions.env` for this preparation; `undefined` without an environment. */
325-    readonly env: ExecutionEnv | undefined;
326-    /** Sections already in effect after replaying the active transcript. */
327-    readonly shown: Readonly<Record<string, string>>;
328-    /** Committed document reads. */
329-    readonly read: DocumentReader;
330-};
331-/** One system prompt section; the agent's sections render in order before each request. */
332-export type PromptSection<Tool extends ToolRegistration = ToolRegistration> = {
333-    readonly key: string;
334-    render(input: PromptInput<Tool>, context: Context): string | undefined | Promise<string | undefined>;
335-    /** Default true: wrap the text as `<key>\n...\n</key>`. */
336-    readonly tag?: boolean;
337-};
338-/** Built by `hook()`; matches tasks by name. */
339-export type HookRegistration = {
340-    readonly task: string;
341-    readonly handlers: object;
342-};
343-/** Built by `wrapTool()` and `wrapSection()`; targets a tool name or a section key. Wrappers are pure. */
344-export type Wrap<Tool extends ToolRegistration = ToolRegistration> = {
345-    readonly tool: string;
445-    } | null;
446-    /** Replaces the stored filter as a whole; tools loaded with `control.addTools` are in its `add`. */
447-    readonly modelTools?: readonly ToolRegistration[] | {
448-        readonly remove?: readonly ToolRegistration[];
449-        readonly add?: readonly ToolRegistration[];
450-    } | null;
451-    readonly instructions?: string | null;
452-    readonly cwd?: string | null;
453-    /** `configure()` throws a `RangeError` unless it is an integer `1` or more (or `null`). */
454-    readonly maxTurns?: number | null;
455-    /** Replaces the stored settings as a whole; `configure()` throws a `RangeError` unless every token count is an integer `0` or more. */
456-    readonly compaction?: CompactionSettings | null;
457-};
458-/** A conversation's agent resolved against a registry snapshot and the settings. */
459-export type Agent<Tool extends ToolRegistration = ToolRegistration> = {
460-    readonly model?: ModelRef;
461-    readonly thinkingLevel: ModelThinkingLevel;
462-    readonly extensions: readonly Extension<Tool>[];
463-    /** The tools a request offers, in order: enabled, callable by the model, and selected by `modelTools`. */
464-    readonly tools: readonly Tool[];
465-    /** The tools nested calls (`executeTool()`) resolve among, in order: enabled and callable by tools. */
466-    readonly callable: readonly Tool[];
467-    /** Enabled deferred tools the model may call and is not offered yet, in registry order: what `tool_search` loads. */
468-    readonly deferred: readonly Tool[];
469-    /** Extension sections, then `instructions` when set. */
470:    readonly sections: readonly PromptSection<Tool>[];

